const vendor = $('Get Vendor Record').first().json;
const response = $input.first().json;
const body = response.data || '';
const rssUrl = vendor.blog_rss_url;

if (typeof body !== 'string' || body.length < 50 || !/<(rss|feed|channel)[\s>]/i.test(body)) {
  return { valid: false };
}

const datePatterns = [
  /<pubDate>([^<]+)<\/pubDate>/gi,
  /<published>([^<]+)<\/published>/gi,
  /<updated>([^<]+)<\/updated>/gi,
  /<dc:date>([^<]+)<\/dc:date>/gi
];

let bestDate = null;
let bestDateObj = null;

for (const pattern of datePatterns) {
  let match;
  while ((match = pattern.exec(body)) !== null) {
    const d = new Date(match[1].trim());
    if (!isNaN(d.getTime())) {
      if (!bestDateObj || d > bestDateObj) {
        bestDateObj = d;
        bestDate = d.toISOString().split('T')[0];
      }
    }
  }
}

if (bestDate) {
  return {
    valid: true,
    blog_url: vendor.blog_url,
    blog_rss_url: rssUrl,
    latest_post_date: bestDate,
    confidence: 'high',
    notes: 'Date from stored RSS feed'
  };
} else {
  return { valid: false };
}

