const raw = $input.first().json;
const parsed = raw.output || raw;
return { blog_url: parsed.blog_url || null };

const blogUrl = $('Extract Blog URL').first().json.blog_url;
const response = $input.first().json;
const html = response.data || '';

// Parse <link> tags for RSS/Atom feeds
const linkTags = html.match(/<link[^>]+>/gi) || [];
let rssFromTag = null;

for (const tag of linkTags) {
  if (/type\s*=\s*["']application\/(rss|atom)\+xml["']/i.test(tag)) {
    const hrefMatch = tag.match(/href\s*=\s*["']([^"']+)["']/i);
    if (hrefMatch) {
      rssFromTag = hrefMatch[1];
      break;
    }
  }
}

const candidates = [];

if (rssFromTag) {
  // Resolve relative URL
  let fullUrl = rssFromTag;
  if (rssFromTag.startsWith('/')) {
    try {
      const base = new URL(blogUrl);
      fullUrl = base.origin + rssFromTag;
    } catch (e) {}
  } else if (!rssFromTag.startsWith('http')) {
    fullUrl = blogUrl.replace(/\/+$/, '') + '/' + rssFromTag;
  }
  candidates.push({ rss_url: fullUrl, source: 'link_tag' });
} else {
  // Try common RSS paths
  const base = blogUrl.replace(/\/+$/, '');
  let origin;
  try { origin = new URL(blogUrl).origin; } catch (e) { origin = base; }

  const paths = [
    origin + '/feed/',
    origin + '/feed',
    base + '/feed/',
    base + '/feed',
    origin + '/blog/feed/',
    origin + '/blog/feed',
    base + '/rss',
    base + '/rss.xml',
    base + '/feed.xml',
    base + '/atom.xml',
    origin + '/feed.xml',
    origin + '/rss'
  ];

  // Deduplicate
  const seen = new Set();
  for (const p of paths) {
    if (!seen.has(p)) {
      seen.add(p);
      candidates.push({ rss_url: p, source: 'common_path' });
    }
  }
}

return candidates;

const items = $input.all();
const candidates = $('Discover RSS Candidates').all();
const blogUrl = $('Extract Blog URL').first().json.blog_url;

// Collect RSS responses with their candidate URLs
const feeds = [];
for (let i = 0; i < items.length; i++) {
  const data = items[i].json.data || '';
  const error = items[i].json.error?.message || '';
  const url = candidates[i]?.json?.rss_url || 'unknown';
  if (data && typeof data === 'string' && data.length > 50) {
    feeds.push({ url: url, content: data.substring(0, 3000) });
  }
}

// Get blog page HTML as fallback
let html = '';
try {
  const pageData = $('Fetch Blog Page').first().json;
  html = (pageData.data || '').substring(0, 12000);
} catch (e) {}

return {
  blog_url: blogUrl,
  feeds: JSON.stringify(feeds, null, 2),
  html: html
};

