return {
  blog_url: null,
  blog_rss_url: null,
  latest_post_date: null,
  confidence: 'high',
  notes: 'No blog found for this vendor',
  needs_ai: false
};

const raw = $input.first().json;
const vendor = $('Get Vendor Record').first().json;

// Handle different input shapes:
// - From stored RSS path: {blog_url, blog_rss_url, latest_post_date, ...}
// - From agent path: {output: {blog_rss_url, latest_post_date, confidence, notes}}
// - From no-blog path: {blog_url: null, ...}
let parsed;
if (raw.output && typeof raw.output === 'object') {
  parsed = raw.output;
} else {
  parsed = raw;
}

// Resolve blog_url from available sources
let blogUrl = parsed.blog_url || null;
if (!blogUrl) {
  try { blogUrl = $('Extract Blog URL').first().json.blog_url; } catch (e) {}
}
if (!blogUrl) {
  blogUrl = vendor.blog_url || null;
}

let blogRssUrl = parsed.blog_rss_url || null;
let dateStr = null;
let daysAgo = null;

if (parsed.latest_post_date && /^\d{4}-\d{2}-\d{2}$/.test(parsed.latest_post_date)) {
  dateStr = parsed.latest_post_date;
  const d = new Date(dateStr + 'T00:00:00Z').getTime();
  if (!isNaN(d)) {
    daysAgo = Math.floor((Date.now() - d) / 86400000);
    if (daysAgo < 0) daysAgo = 0;
    if (daysAgo > 3650) daysAgo = 3650;
  }
}

const noBlog = !blogUrl;

return {
  record_id: vendor.id,
  blog_url: blogUrl,
  blog_rss_url: blogRssUrl,
  blog_last_post_date: dateStr,
  blog_last_post_days_ago: daysAgo,
  blog_checked_at: new Date().toISOString(),
  status: noBlog ? 'success' : (daysAgo !== null ? 'success' : 'partial'),
  fields_updated: blogUrl
    ? ['blog_url','blog_rss_url','blog_last_post_date','blog_last_post_days_ago','blog_checked_at']
    : ['blog_checked_at'],
  note: noBlog ? 'No blog found for this vendor' : (parsed.notes || null)
};

const input = $input.first().json;

return {
  record_id: input.record_id,
  workflow: 'W-BlogRecency',
  status: input.status || 'success',
  fields_updated: input.fields_updated || [],
  error: input.error || null,
  note: input.note || null
};
